#include "StyleCaptionConfig.h"
#include <fstream>
namespace{std::string U(const std::filesystem::path&p){auto s=p.generic_u8string();return{reinterpret_cast<const char*>(s.data()),s.size()};}std::string E(const std::string&s){std::string r;for(char c:s){if(c=='\\')r+="\\\\";else if(c=='\"')r+="\\\"";else r+=c;}return r;}}
bool SaveCaptionConfig(const StyleCaptionConfig&c,const std::filesystem::path&p,std::string&e){std::filesystem::create_directories(p.parent_path());std::ofstream s(p,std::ios::binary|std::ios::trunc);if(!s){e="Could not write caption_config.json.";return false;}s<<"{\n\"version\":1,\n\"dataset\":\""<<E(U(c.datasetPath))<<"\",\n\"mode\":\""<<c.mode<<"\",\n\"model\":\""<<E(c.model)<<"\",\n\"general_threshold\":"<<c.generalThreshold<<",\n\"character_threshold\":"<<c.characterThreshold<<",\n\"include_rating_tags\":"<<(c.includeRatingTags?"true":"false")<<",\n\"include_character_tags\":"<<(c.includeCharacterTags?"true":"false")<<",\n\"replace_underscores\":"<<(c.replaceUnderscores?"true":"false")<<",\n\"overwrite_existing\":"<<(c.overwriteExisting?"true":"false")<<",\n\"items\":[";for(size_t i=0;i<c.items.size();++i)s<<(i?",":"")<<"\""<<E(c.items[i])<<"\"";s<<"]\n}\n";return true;}
